import java.util.*;

public List<String> crosswordPuzzle(List<String> gridIn, String wordStr) {
    char[][] grid = new char[10][10];
    for (int r = 0; r < 10; r++) grid[r] = gridIn.get(r).toCharArray();
    String[] words = wordStr.split(";");
    boolean[] used = new boolean[words.length];
    solve(grid, words, used, 0);
    List<String> out = new ArrayList<>();
    for (char[] row : grid) out.add(new String(row));
    return out;
}

private boolean solve(char[][] grid, String[] words, boolean[] used, int placed) {
    if (placed == words.length) return true;
    for (int w = 0; w < words.length; w++) {
        if (used[w]) continue;
        String word = words[w];
        for (int r = 0; r < 10; r++) {
            for (int c = 0; c < 10; c++) {
                // horizontal
                if (fitsH(grid, r, c, word)) {
                    char[] backup = placeH(grid, r, c, word);
                    used[w] = true;
                    if (solve(grid, words, used, placed + 1)) return true;
                    used[w] = false;
                    unplaceH(grid, r, c, backup);
                }
                // vertical
                if (fitsV(grid, r, c, word)) {
                    char[] backup = placeV(grid, r, c, word);
                    used[w] = true;
                    if (solve(grid, words, used, placed + 1)) return true;
                    used[w] = false;
                    unplaceV(grid, r, c, backup);
                }
            }
        }
    }
    return false;
}

private boolean fitsH(char[][] g, int r, int c, String w) {
    int len = w.length();
    if (c + len > 10) return false;
    if (c > 0 && g[r][c - 1] != '+') return false;          // left boundary
    if (c + len < 10 && g[r][c + len] != '+') return false; // right boundary
    for (int i = 0; i < len; i++) {
        char cell = g[r][c + i];
        if (cell != '-' && cell != w.charAt(i)) return false;
    }
    return true;
}

private char[] placeH(char[][] g, int r, int c, String w) {
    char[] backup = new char[w.length()];
    for (int i = 0; i < w.length(); i++) { backup[i] = g[r][c + i]; g[r][c + i] = w.charAt(i); }
    return backup;
}

private void unplaceH(char[][] g, int r, int c, char[] backup) {
    for (int i = 0; i < backup.length; i++) g[r][c + i] = backup[i];
}

private boolean fitsV(char[][] g, int r, int c, String w) {
    int len = w.length();
    if (r + len > 10) return false;
    if (r > 0 && g[r - 1][c] != '+') return false;
    if (r + len < 10 && g[r + len][c] != '+') return false;
    for (int i = 0; i < len; i++) {
        char cell = g[r + i][c];
        if (cell != '-' && cell != w.charAt(i)) return false;
    }
    return true;
}

private char[] placeV(char[][] g, int r, int c, String w) {
    char[] backup = new char[w.length()];
    for (int i = 0; i < w.length(); i++) { backup[i] = g[r + i][c]; g[r + i][c] = w.charAt(i); }
    return backup;
}

private void unplaceV(char[][] g, int r, int c, char[] backup) {
    for (int i = 0; i < backup.length; i++) g[r + i][c] = backup[i];
}

