def crossword_puzzle(grid_in: list[str], word_str: str) -> list[str]:
    grid = [list(row) for row in grid_in]
    words = word_str.split(';')
    used = [False] * len(words)

    def fits(r, c, w, dr, dc):
        ln = len(w)
        er, ec = r + dr * (ln - 1), c + dc * (ln - 1)
        if er >= 10 or ec >= 10:
            return False
        # boundary before start and after end must be '+' or edge
        br, bc = r - dr, c - dc
        ar, ac = r + dr * ln, c + dc * ln
        if 0 <= br < 10 and 0 <= bc < 10 and grid[br][bc] != '+':
            return False
        if 0 <= ar < 10 and 0 <= ac < 10 and grid[ar][ac] != '+':
            return False
        for i in range(ln):
            cell = grid[r + dr * i][c + dc * i]
            if cell != '-' and cell != w[i]:
                return False
        return True

    def place(r, c, w, dr, dc):
        backup = []
        for i in range(len(w)):
            rr, cc = r + dr * i, c + dc * i
            backup.append(grid[rr][cc])
            grid[rr][cc] = w[i]
        return backup

    def unplace(r, c, w, dr, dc, backup):
        for i in range(len(w)):
            grid[r + dr * i][c + dc * i] = backup[i]

    def solve(placed):
        if placed == len(words):
            return True
        for wi, w in enumerate(words):
            if used[wi]:
                continue
            for r in range(10):
                for c in range(10):
                    for dr, dc in ((0, 1), (1, 0)):   # horizontal, vertical
                        if fits(r, c, w, dr, dc):
                            backup = place(r, c, w, dr, dc)
                            used[wi] = True
                            if solve(placed + 1):
                                return True
                            used[wi] = False
                            unplace(r, c, w, dr, dc, backup)
        return False

    solve(0)
    return [''.join(row) for row in grid]

