import java.util.*;

public List<String> crosswordPuzzle(List<String> gridIn, String wordStr) {
    char[][] grid = new char[10][10];
    for (int r = 0; r < 10; r++) grid[r] = gridIn.get(r).toCharArray();
    String[] words = wordStr.split(";");

    List<int[][]> slots = new ArrayList<>();
    // horizontal slots
    for (int r = 0; r < 10; r++) {
        int c = 0;
        while (c < 10) {
            if (grid[r][c] == '-') {
                int start = c;
                while (c < 10 && grid[r][c] == '-') c++;
                if (c - start >= 2) {
                    int[][] cells = new int[c - start][2];
                    for (int i = 0; i < c - start; i++) cells[i] = new int[]{r, start + i};
                    slots.add(cells);
                }
            } else c++;
        }
    }
    // vertical slots
    for (int c = 0; c < 10; c++) {
        int r = 0;
        while (r < 10) {
            if (grid[r][c] == '-') {
                int start = r;
                while (r < 10 && grid[r][c] == '-') r++;
                if (r - start >= 2) {
                    int[][] cells = new int[r - start][2];
                    for (int i = 0; i < r - start; i++) cells[i] = new int[]{start + i, c};
                    slots.add(cells);
                }
            } else r++;
        }
    }

    boolean[] used = new boolean[words.length];
    backtrack(grid, slots, words, used, 0);

    List<String> out = new ArrayList<>();
    for (char[] row : grid) out.add(new String(row));
    return out;
}

private boolean backtrack(char[][] grid, List<int[][]> slots,
                          String[] words, boolean[] used, int i) {
    if (i == slots.size()) return true;
    int[][] slot = slots.get(i);
    for (int w = 0; w < words.length; w++) {
        if (used[w] || words[w].length() != slot.length) continue;
        String word = words[w];
        boolean fits = true;
        for (int j = 0; j < slot.length; j++) {
            char cell = grid[slot[j][0]][slot[j][1]];
            if (cell != '-' && cell != word.charAt(j)) { fits = false; break; }
        }
        if (!fits) continue;
        char[] backup = new char[slot.length];
        for (int j = 0; j < slot.length; j++) {
            backup[j] = grid[slot[j][0]][slot[j][1]];
            grid[slot[j][0]][slot[j][1]] = word.charAt(j);
        }
        used[w] = true;
        if (backtrack(grid, slots, words, used, i + 1)) return true;
        used[w] = false;
        for (int j = 0; j < slot.length; j++) grid[slot[j][0]][slot[j][1]] = backup[j];
    }
    return false;
}

