def crossword_puzzle(grid_in: list[str], word_str: str) -> list[str]:
    grid = [list(row) for row in grid_in]
    words = word_str.split(';')

    slots = []
    for r in range(10):                       # horizontal slots
        c = 0
        while c < 10:
            if grid[r][c] == '-':
                start = c
                while c < 10 and grid[r][c] == '-':
                    c += 1
                if c - start >= 2:
                    slots.append([(r, x) for x in range(start, c)])
            else:
                c += 1
    for c in range(10):                       # vertical slots
        r = 0
        while r < 10:
            if grid[r][c] == '-':
                start = r
                while r < 10 and grid[r][c] == '-':
                    r += 1
                if r - start >= 2:
                    slots.append([(x, c) for x in range(start, r)])
            else:
                r += 1

    used = set()

    def backtrack(i):
        if i == len(slots):
            return True
        slot = slots[i]
        for w in words:
            if w in used or len(w) != len(slot):
                continue
            if all(grid[r][c] == '-' or grid[r][c] == w[j]
                   for j, (r, c) in enumerate(slot)):
                backup = [grid[r][c] for (r, c) in slot]
                for j, (r, c) in enumerate(slot):
                    grid[r][c] = w[j]
                used.add(w)
                if backtrack(i + 1):
                    return True
                used.remove(w)
                for j, (r, c) in enumerate(slot):
                    grid[r][c] = backup[j]
        return False

    backtrack(0)
    return [''.join(row) for row in grid]
